export const originalText='魔能斩 E LDRITCH S MITE\n先决条件：第 5\n级，刃之魔契\n每回合一次， 当你用契约武器命中一个生物时， 你\n可以消耗一个邪术师法术位，以此对目标造成额外\n1d8+ 每法术位等级 1d8 点的力场伤害，如果目标的体\n型在巨型或以下，则你还可以将他击入 倒地 Prone 。'
export function eldritchSource(namespace:string){return{id:'eldritch-smite',name:'魔能斩',summary:'契约武器命中时消耗邪术师法术位追加力场伤害，可击倒巨型或更小的生物。',description:originalText,automation:'full' as const,classRequirements:[{classId:'warlock',minimumLevel:5}],classChoiceRequirements:[{classId:'warlock',groupId:'pact-boon',anyOf:['blade']},{classId:'warlock',groupId:'eldritch-invocations',anyOf:[namespace+':eldritch-smite']}]}}
export function eldritchActivities():Dnd5eActivityDefinitionV1[]{return([3,4,5]as const).flatMap(slot=>[false,true].map(prone=>({schemaVersion:1,id:`eldritch-smite-slot${slot}${prone?'-prone':''}`,name:`魔能斩·${slot}环${prone?'·击倒':''}`,activation:{kind:'free'},invocation:{kind:'triggered',event:'attack-hit',confirmation:'actor-choice',retention:'single-event'},target:{kind:'creature',count:1,relation:'any'},requirements:[{kind:'class-level',classId:'warlock',minimum:slot===3?5:slot===4?7:9,...(slot<5?{maximum:slot===3?6:8}:{})},{kind:'attack-pact-weapon'},{kind:'once-per-turn',key:'eldritch-smite'},...(prone?[{kind:'size-rank' as const,subject:'target' as const,maximum:4}]:[])],consumption:[{kind:'resource',resourceId:'dnd5e-pact-slot',amount:{kind:'constant',value:1},consumeOn:'resolve'}],outcomes:[{id:'smite',when:{kind:'always'},operations:[{id:'force',kind:'damage',target:'target',amount:{kind:'dice',rollId:'smite-force',count:slot+1,sides:8},damageType:'force',magical:true,critical:'double-dice'},...(prone?[{id:'prone',kind:'apply-effect' as const,target:'target' as const,effectId:'eldritch-prone'}]:[])]}],...(prone?{effects:[{schemaVersion:1 as const,id:'eldritch-prone',name:'魔能斩·倒地',stacking:'replace' as const,duration:{kind:'permanent' as const},conditions:['prone' as const],magical:true}]}:{}),automation:automationCapabilityFromLegacyStatus('full'),legacySource:{kind:'feature',id:'eldritch-smite'}})))}

